def test_real_cash_flow_total_keeps_its_six_month_duration_and_only_its_row() -> None:
    ledger = _ledger(
        "Cash generated by operating activities 82,627 53,887\n\n"
        "Cash paid for income taxes 20,397 14,052",
        quarter="Q2_2026",
        table_context="Six Months Ended March 28, March 29, 2026 2025 (In millions)",
    )
    facts = ledger.lookup(metric_id="operating_cash_flow")
    assert [(fact.fact_period, fact.normalized_value) for fact in facts] == [
        ("Q2_2026", Decimal("82627000000")),
        ("Q2_2025", Decimal("53887000000")),
    ]
    assert all(fact.period_type == "six_months" for fact in facts)
    assert all(fact.provenance["period_type"] == "six_months" for fact in facts)
    assert all("taxes" not in fact.evidence_text for fact in facts)


