def test_tesla_sample_pdf_yoy_column_is_not_misattributed_to_q2_2025() -> None:
    from pathlib import Path

    from document_loader import get_document_period, load_pdf_chunks

    source = Path(__file__).resolve().parents[2] / "demo" / "documents" / "Tesla_sample.pdf"
    chunks = load_pdf_chunks(source, ocr_enabled=False)
    document_period = get_document_period(chunks)
    rows = [
        Evidence(
            content=str(chunk.text or ""),
            source=source.name,
            company="Tesla",
            confidence=1.0,
            metadata={
                "chunk_id": f"tesla-real-{index}",
                "quarter": document_period,
                "page": chunk.page,
                "section": chunk.section,
                "content_type": chunk.content_type,
                "table_context": str(getattr(chunk, "table_context", "") or ""),
            },
        )
        for index, chunk in enumerate(chunks)
        if "Metric: Total revenues" in str(chunk.text or "")
        and "YoY: -3%" in str(chunk.text or "")
    ]
    ledger = FactLedger.from_evidence(rows)

    assert ledger.lookup(
        company="Tesla", metric_id="revenue", period="Q2_2025", growth_basis="yoy"
    ) == ()
    assert {
        fact.normalized_value
        for fact in ledger.lookup(
            company="Tesla", metric_id="revenue", period="Q4_2025", growth_basis="yoy"
        )
    } == {Decimal("-3")}


