def test_quarter_query_prefers_quarter_fact_over_same_period_ytd_subtotal() -> None:
    from core.required_fact_plan import _preferred_fact

    quarter = SimpleNamespace(
        evidence_text="Net income $ 29,578",
        section="Three Months Ended",
        period_type="fiscal_quarter",
        table_row_period="Q2_FY2026",
        table_column_period="Q2_FY2026",
        fact_period="Q2_FY2026",
        confidence=1.0,
        normalized_value=Decimal("29578000000"),
        fact_id="quarter",
    )
    year_to_date = SimpleNamespace(
        evidence_text="Net income 71,675",
        section="Six Months Ended",
        period_type="six_months",
        table_row_period="Q2_FY2026",
        table_column_period="Q2_FY2026",
        fact_period="Q2_FY2026",
        confidence=1.0,
        normalized_value=Decimal("71675000000"),
        fact_id="six-months",
    )

    assert _preferred_fact(
        (year_to_date, quarter),
        "net_income",
        question="总结苹果公司 2026 年第二季度的财务表现",
    ).fact_id == "quarter"
    assert _preferred_fact(
        (year_to_date, quarter),
        "net_income",
        question="Compare Apple and Tesla's financial performance",
        requested_period="Q2_FY2026",
    ).fact_id == "quarter"
    assert _preferred_fact(
        (quarter, year_to_date),
        "net_income",
        question="Summarize Apple's first six months of FY2026",
    ).fact_id == "six-months"


