def test_automotive_gross_margin_is_not_used_as_consolidated_gross_margin() -> None:
    from core.financial_grounding import canonical_metrics
    from retrieval.periods import extract_metrics

    ledger = _ledger(
        "\n".join(
            (
                "Structured financial table row (PDF page 31).",
                "TABLE COLUMNS: Comparative columns: Q4-2025",
                "Financial table row | Metric: Automotive gross margin (GAAP) | Q4 2025: 20.4%",
                "Financial table row | Metric: Total GAAP gross margin | Q4 2025: 20.1%",
            )
        ),
        company="Tesla",
        quarter="Q4_FY2025",
        content_type="table",
        table_context="Comparative columns: Q4-2025",
    )

    assert [fact.normalized_value for fact in ledger.lookup(
        company="Tesla", metric_id="gross_margin", period="Q4_2025"
    )] == [Decimal("20.1")]
    assert [fact.normalized_value for fact in ledger.lookup(
        company="Tesla", metric_id="automotive_gross_margin", period="Q4_2025"
    )] == [Decimal("20.4")]
    assert canonical_metrics("What was Tesla automotive gross margin in Q4 2025?") == (
        "automotive_gross_margin",
    )
    assert extract_metrics("What was Tesla automotive gross margin in Q4 2025?") == (
        "automotive_gross_margin",
    )


