def test_tesla_year_columns_remain_fiscal_year_facts_not_q4_actuals() -> None:
    ledger = _ledger(
        "Tesla Q4/FY2025 Update\nFINANCIAL SUMMARY\n"
        "Total revenues 53,823 81,462 96,773 97,690 94,827 -3%\n"
        "Net income attributable to common stockholders (GAAP) "
        "5,519 12,556 14,997 7,091 3,794 -46%",
        company="Tesla",
        quarter="Q4_2025",
        table_context=(
            "FINANCIAL SUMMARY ($ in millions)\n"
            "context/header row 1: 2021 | 2022 | 2023 | 2024 | 2025 | YoY"
        ),
    )

    revenue = ledger.lookup(company="Tesla", metric_id="revenue")
    net_income = ledger.lookup(company="Tesla", metric_id="net_income")
    assert [(fact.fact_period, fact.normalized_value) for fact in revenue] == [
        ("FY2021", Decimal("53823000000")),
        ("FY2022", Decimal("81462000000")),
        ("FY2023", Decimal("96773000000")),
        ("FY2024", Decimal("97690000000")),
        ("FY2025", Decimal("94827000000")),
    ]
    assert [(fact.fact_period, fact.normalized_value) for fact in net_income] == [
        ("FY2021", Decimal("5519000000")),
        ("FY2022", Decimal("12556000000")),
        ("FY2023", Decimal("14997000000")),
        ("FY2024", Decimal("7091000000")),
        ("FY2025", Decimal("3794000000")),
    ]
    assert all(fact.fiscal_quarter is None for fact in (*revenue, *net_income))
    assert all(fact.period_type == "fiscal_year" for fact in (*revenue, *net_income))

    from core.required_fact_plan import _company_reporting_period

    assert _company_reporting_period(ledger, "Tesla", "revenue") == "FY2025"


