def test_nvidia_segment_revenue_rows_keep_distinct_metrics_from_heading() -> None:
    data_center = _ledger(
        "Data Center\n\nFirst-quarter revenue was a record $75. 2 billion, up 21% from the previous quarter and up 92% from a year ago.",
        company="NVIDIA",
        quarter="Q1_FY2027",
    )
    edge = _ledger(
        "Edge Computing\n\nFirst-quarter Edge Computing revenue was $6. 4 billion, up 10% from the previous quarter and up 29% from a year ago.",
        company="NVIDIA",
        quarter="Q1_FY2027",
    )

    data_center_facts = data_center.lookup(metric_id="data_center_revenue", period="Q1_FY2027")
    edge_facts = edge.lookup(metric_id="edge_computing_revenue", period="Q1_FY2027")

    assert [fact.normalized_value for fact in data_center_facts] == [Decimal("75200000000")]
    assert [fact.normalized_value for fact in edge_facts] == [Decimal("6400000000")]
    assert not data_center.lookup(metric_id="revenue")
    assert not edge.lookup(metric_id="revenue")


