def test_tesla_eps_rows_are_distinguished_from_income_used_to_compute_eps() -> None:
    ledger = _ledger(
        "In millions of USD or shares as applicable, except per share data "
        "Q4-2024 Q1-2025 Q2-2025 Q3-2025 Q4-2025\n"
        "Net income used in computing diluted EPS attributable to common stockholders "
        "(non-GAAP) 2,104 934 1,393 1,770 1,761\n"
        "EPS attributable to common stockholders, diluted (GAAP) "
        "0.60 0.12 0.33 0.39 0.24\n"
        "EPS attributable to common stockholders, diluted (non-GAAP) "
        "0.60 0.27 0.40 0.50 0.50",
        company="Tesla",
        quarter="Unknown",
    )

    q2_eps = ledger.lookup(company="Tesla", metric_id="eps", period="Q2_2025")
    assert {fact.normalized_value for fact in q2_eps} == {Decimal("0.33"), Decimal("0.40")}
    assert all(fact.unit == "per_share" for fact in q2_eps)
    assert all("net income used in computing" not in fact.evidence_text.casefold() for fact in q2_eps)


@pytest.mark.parametrize("unit,value", [("thousands", "81600000"), ("millions", "81600000000"), ("billions", "81600000000000")])
def test_table_scale_is_taken_from_explicit_units(unit: str, value: str) -> None:
    ledger = _ledger("Revenue $ 81,600 $ 44,062", table_context=f"(In {unit})")
    assert ledger.lookup(metric_id="revenue")[0].normalized_value == Decimal(value)


def test_primary_statement_scale_wins_over_share_count_exception() -> None:
    ledger = _ledger(
        "Financial table row — Metric: Total net sales | Q2 FY2026: 111,184 | Q2 FY2025: 95,359",
        table_context=(
            "(In millions, except number of shares, which are reflected in thousands, "
            "and per-share amounts) Q2 FY2026 Q2 FY2025"
        ),
    )

    assert {fact.normalized_value for fact in ledger.lookup(metric_id="revenue")} == {
        Decimal("111184000000"),
        Decimal("95359000000"),
    }


def test_prose_scaled_amount_is_not_scaled_again_by_table_header() -> None:
    ledger = _ledger("Revenue was $81.6 billion.", table_context="(In millions)")
    assert ledger.lookup(metric_id="revenue")[0].normalized_value == Decimal("81600000000")


def test_eps_not_multiplied_by_statement_amount_scale() -> None:
    ledger = _ledger("Diluted earnings per share $2.01 $1.69", table_context="(In millions, except per share amounts)")
    assert ledger.lookup(metric_id="eps")[0].normalized_value == Decimal("2.01")


def test_repeated_metric_clauses_keep_both_current_and_prior_operands() -> None:
    ledger = _ledger("Current revenue $120B; prior revenue $100B.", company="NVIDIA")
    facts = ledger.lookup(metric_id="revenue")
    assert {fact.normalized_value for fact in facts} == {Decimal("120000000000"), Decimal("100000000000")}
    assert all(";" not in fact.evidence_text for fact in facts)


def test_growth_provenance_is_kept_without_creating_extra_amount_facts() -> None:
    ledger = _ledger(
        "NVIDIA Q1 FY2027 Record Data Center revenue of $75.2 billion, up 92% from a year ago.",
        company="NVIDIA",
    )
    facts = ledger.lookup(metric_id="data_center_revenue")
    assert [fact.normalized_value for fact in facts] == [Decimal("75200000000")]
    assert "up 92% from a year ago" in facts[0].evidence_text


def test_revenue_under_data_center_section_is_not_misclassified_as_total_revenue() -> None:
    ledger = _ledger(
        "Data Center\n\nFirst-quarter revenue was a record $75. 2 billion, "
        "up 21% from the previous quarter and up 92% from a year ago.",
        company="NVIDIA",
        quarter="Q1_FY2027",
    )

    data_center = ledger.lookup(metric_id="data_center_revenue", period="Q1_FY2027")
    assert [fact.normalized_value for fact in data_center] == [Decimal("75200000000")]
    assert ledger.lookup(metric_id="revenue", period="Q1_FY2027") == ()
